        /// <summary>Sets one value by name. Unknown names are ignored rather than thrown on —
        /// the callers are UI, and a window that throws in OnGUI throws every frame.</summary>
        internal static void SetByName(string name, double value)
        {
            Action<double> write;
            if (name == null || !setters.TryGetValue(name, out write)) return;

            write(value);
            Refingerprint();
        }

