            Mix(ref h, "PoiJettyShelterMin", PoiJettyShelterMin);
            Mix(ref h, "DetailSheetWidthMm", DetailSheetWidthMm);
            Mix(ref h, "DetailSheetHeightMm", DetailSheetHeightMm);
            Mix(ref h, "DetailSheetMarginMm", DetailSheetMarginMm);
            Mix(ref h, "PoiScaleDenominator", PoiScaleDenominator);
            Fingerprint = h;
        }

        static void Mix(ref ulong h, string name, double value)
        {
            Mix(ref h, name);
            Mix(ref h, value.ToString("R", CultureInfo.InvariantCulture));
        }

        static void Mix(ref ulong h, string s)
        {
            for (int i = 0; i < s.Length; i++)
            {
                h ^= s[i];
                h *= 1099511628211UL;
            }
            h ^= (byte)'|';
            h *= 1099511628211UL;
        }

        /// <summary>One line for a log: where the numbers came from and what they add up to.</summary>
        public static string Describe()
        {
            string source = LoadedFrom ?? "compiled defaults";
            int overridden = 0;
            for (int i = 0; i < parameters.Count; i++) if (parameters[i].IsOverridden) overridden++;

            string faults = problems.Count == 0 ? "" : $", {problems.Count} problem(s)";
            return $"tuning {Fingerprint:X16} from {source} ({overridden} overridden{faults})";
        }
    }
}
